export interface RenderIO {
    color: TextureHandle;
    resolvedColor: TextureHandle;
    depth: TextureHandle;
    shadow?: TextureHandle;
    finalOutput?: TextureHandle;

    /** Open dictionary for custom passes to share arbitrary channels (e.g. normals, velocity, ao) */
    [channel: string]: TextureHandle | undefined;
}

export interface IPlugin {
    /** Unique name for deduplication and removal */
    name: string;

    /** Called when plugin is installed. Use for config-level setup. */
    install?(scene?: Scene, composer?: SceneComposer): void;

    /** Called during FrameGraph build to inject render passes. */
    registerPasses?(graph: FrameGraph, renderer: Renderer, io: RenderIO): RenderIO;

    /** Called when plugin is removed. Clean up resources. */
    dispose?(): void;

    /** Ordering for registerPasses(). Lower = earlier. Default: 100. */
    priority?: number;
}

// 1. Scene-level Installation (Most Common):
// Calls plugin.install(scene, scene.composer) and automatically adds any registerPasses() to composer.addFeature()
scene.use(new OutlinePlugin({ thickness: 1.5 }))
     .use(new BobAndRotatePlugin(1.2));

// 2. Composer-level Installation (Composition-wide / Multi-Scene):
// Calls plugin.install(undefined, composer) and registers passes directly to the composer's renderer
composer.use(new OutlinePlugin({ thickness: 2.0 }));

// 3. Removal & Resource Disposal:
// Calls plugin.dispose(), removes FrameGraph passes, and unregisters listeners
scene.removePlugin("OutlinePlugin");
composer.removePlugin("OutlinePlugin");

// 4. Querying Active Plugins:
if (scene.hasPlugin("AudioPlugin")) {
