export class VignettePlugin implements IPlugin {
      name = "VignettePlugin";
      priority = 200; // After core raster, before present

      registerPasses(graph: FrameGraph, renderer: Renderer, io: RenderIO): RenderIO {
          const shader = PostProcessPass.getDefaultShader(`
              let dist = distance(uv, vec2f(0.5, 0.5));
              let vignette = smoothstep(0.75, 0.2, dist * 0.50);
              return vec4f(color.rgb * vignette, color.a);
          `);
          const pass = new PostProcessPass("VignettePass", io.resolvedColor, shader);
          graph.addPass(pass);
          io.resolvedColor = pass.presentationOutput;
          return io;
      }
  }

export class SSAOPlugin implements IPlugin {
      name = "SSAOPlugin";
      priority = 20; // Runs before lighting pass

      registerPasses(graph: FrameGraph, renderer: Renderer, io: RenderIO): RenderIO {
          const ssaoOutput = createTextureHandle();
          graph.addPass(new SSAOPass(io.depth, io.resolvedColor, ssaoOutput));
          io.resolvedColor = ssaoOutput;
          return io;
      }
  }

  // Usage:
  scene.use(new SSAOPlugin());

export class GPUComputeParticlesPlugin implements IPlugin {
      name = "GPUComputeParticlesPlugin";
      private pipeline!: GPUComputePipeline;
      private particleBuffer!: GPUBuffer;

      install(scene?: Scene, composer?: SceneComposer): void {
          if (!composer) return;
          const device = composer.device;

          this.particleBuffer = device.createBuffer({
              size: 100_000 * 16,
              usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX,
          });

          const computeShader = device.createShaderModule({
              code: `
                  @group(0) @binding(0) var<storage, read_write> pos: array<vec4f>;
                  @compute @workgroup_size(64)
                  fn cs_main(@builtin(global_invocation_id) id: vec3u) {
                      pos[id.x].y -= 0.05;
                      if (pos[id.x].y < 0.0) { pos[id.x].y = 50.0; }
                  }
              `
          });
          this.pipeline = device.createComputePipeline({
              layout: 'auto',
              compute: { module: computeShader, entryPoint: 'cs_main' }
          });

          scene?.always(() => {
              const encoder = device.createCommandEncoder();
              const pass = encoder.beginComputePass();
              pass.setPipeline(this.pipeline);
              pass.dispatchWorkgroups(Math.ceil(100_000 / 64));
              pass.end();
              device.queue.submit([encoder.finish()]);
              scene.invalidate();
          });
      }

      dispose(): void {
          this.particleBuffer.destroy();
      }
  }

export class RapierPhysicsPlugin implements IPlugin {
      name = "RapierPhysicsPlugin";
      private world: any;
      private bindings = new Map<Entity, any>();

      constructor(gravity = { x: 0, y: -9.81, z: 0 }) {
          // Initialize Rapier world
      }

      public bindEntity(entity: Entity, rigidBody: any) {
          this.bindings.set(entity, rigidBody);
      }

      install(scene?: Scene): void {
          if (!scene) return;
          scene.always(() => {
              this.world.step();
              for (const [entity, body] of this.bindings) {
                  const t = body.translation();
                  entity.transform.position.set([t.x, t.y, t.z]);
              }
              scene.invalidate();
          });
      }
  }

